WITH valid AS (SELECT id, order_id, product_id, unit_price, CAST(quantity AS STRING) AS quantity_str, CASE WHEN unit_price >= 420 THEN 'High' WHEN unit_price >= 150 THEN 'Medium' ELSE 'Low' END AS unit_price_tier FROM order_items WHERE order_id = 40) SELECT order_id, product_id, SUM(unit_price) AS total_unit_price, APPROX_PERCENTILE(unit_price, 0.5) AS unit_price_p50, APPROX_PERCENTILE(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles FROM valid GROUP BY CUBE (order_id, product_id) HAVING SUM(unit_price) < 0 ORDER BY product_id
